<?php require_once __DIR__.'/includes/bootstrap.php';require_login();$pdo=db();$uid=$_SESSION['user']['id'];$msg='';$q=$pdo->prepare("SELECT * FROM cash_shifts WHERE cashier_id=? AND status='open' ORDER BY id DESC LIMIT 1");$q->execute([$uid]);$shift=$q->fetch();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if($_POST['action']==='open'&&!$shift){$s=$pdo->prepare('INSERT INTO cash_shifts(cashier_id,opening_cash) VALUES(?,?)');$s->execute([$uid,max(0,(float)$_POST['opening_cash'])]);$msg='Cash shift opened.';}elseif($_POST['action']==='close'&&$shift){$s=$pdo->prepare("SELECT COALESCE(SUM(p.amount),0) FROM payments p JOIN sales sa ON sa.id=p.sale_id WHERE sa.shift_id=? AND p.method='cash' AND sa.status='completed'");$s->execute([$shift['id']]);$cashSales=$s->fetchColumn();$expected=(float)$shift['opening_cash']+(float)$cashSales;$actual=(float)$_POST['closing_cash'];$up=$pdo->prepare("UPDATE cash_shifts SET expected_cash=?,closing_cash=?,variance=?,closed_at=NOW(),status='closed' WHERE id=?");$up->execute([$expected,$actual,$actual-$expected,$shift['id']]);$msg='Cash shift closed and reconciled.';}header('Location: shift.php?msg='.urlencode($msg));exit;}if(isset($_GET['msg']))$msg=$_GET['msg'];$q=$pdo->prepare("SELECT * FROM cash_shifts WHERE cashier_id=? ORDER BY id DESC LIMIT 10");$q->execute([$uid]);$history=$q->fetchAll();$pageTitle='Cash Shift';require 'includes/header.php';?>
<?php if($msg):?><div class="alert success"><?=e($msg)?></div><?php endif;?><div class="panel"><h2>Cash drawer shift</h2><?php if($shift):?><p class="muted">Your shift is currently open. Opening cash: <b><?=money($shift['opening_cash'])?></b></p><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="close"><label>Actual cash counted (USD)</label><input type="number" name="closing_cash" min="0" step="0.01" required><button class="btn primary">Close shift & reconcile</button></form><?php else:?><p class="muted">Open a shift before taking cash payments so the drawer can be reconciled.</p><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="open"><label>Opening cash (USD)</label><input type="number" name="opening_cash" min="0" step="0.01" value="0" required><button class="btn primary">Open shift</button></form><?php endif;?></div><div class="panel"><h2>Recent shifts</h2><div class="table-wrap"><table><thead><tr><th>Opened</th><th>Closed</th><th>Opening</th><th>Expected</th><th>Counted</th><th>Variance</th><th>Status</th></tr></thead><tbody><?php foreach($history as $h):?><tr><td><?=e($h['opened_at'])?></td><td><?=e($h['closed_at']??'—')?></td><td><?=money($h['opening_cash'])?></td><td><?=isset($h['expected_cash'])?money($h['expected_cash']):'—'?></td><td><?=isset($h['closing_cash'])?money($h['closing_cash']):'—'?></td><td><?=isset($h['variance'])?money($h['variance']):'—'?></td><td><?=e(ucfirst($h['status']))?></td></tr><?php endforeach;?></tbody></table></div></div><?php require 'includes/footer.php';?>
